fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    if numbers.len() == 0 {
        return result;
    }
    // Initialize the current max as the first element
    let mut current_max = numbers[0];
    result.push(current_max);

    let mut i = 1;
    while i < numbers.len() {
        let n = numbers[i];
        if n > current_max {
            current_max = n;
        }
        result.push(current_max);
        i += 1;
    }

    result
}